//! Replays this crate's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave,
//! compared as text. The corpus is regenerated by `tools/oracle/refresh.sh`;
//! nothing here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_hooks::oracle::{KINDS, run_case};
use focus_js::json::stringify;
use serde_json::{Value, json};

#[test]
fn every_turn_reader_case_gets_upstreams_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut replayed, mut hosts, mut persons, mut unwrapped, mut empty) = (0, 0, 0, 0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default();
        if !KINDS.contains(&kind) {
            continue;
        }
        replayed += 1;
        let answer = run_case(&case);
        match kind {
            "host_envelope" => {
                unwrapped += usize::from(answer.as_str() != case["prompt"].as_str());
            }
            "picker_empty" => empty += usize::from(answer == Value::Bool(true)),
            _ => {
                hosts += usize::from(answer["kind"] == "host");
                persons += usize::from(answer["kind"] == "person");
            }
        }
        let got = stringify(&json!({ "id": case["id"], "out": answer }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    assert!(replayed >= 150, "too few turn reader cases: {replayed}");
    assert!(
        hosts >= 20 && persons >= 10 && unwrapped >= 20 && empty >= 3,
        "{hosts} host turns, {persons} person turns, {unwrapped} envelopes unwrapped, {empty} empty boxes"
    );
    assert!(
        differing.is_empty(),
        "{} of {replayed} cases differ from upstream:\n{}",
        differing.len(),
        differing.join("\n")
    );
}
